    postCompaniesByCompanyIdDataBenchmarks: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                companyId: string;
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                'application/json': {
                    /**
                     * @description Compare against this ACV segment instead of the company's own.
                     * @enum {string}
                     */
                    acvSegment?: 'mice' | 'rabbits' | 'deer' | 'elephants';
                    /**
                     * @description Compare against this ARR stage instead of the company's own.
                     * @enum {string}
                     */
                    arrStage?: 'lt1m' | 'from1to3m' | 'from3to10m' | 'from10to20m' | 'gte20m';
                    /** @description Metrics to compare. Omit for every metric with a peer band. */
                    metricNames?: (
                        | 'mrrGrowthRateAnnual'
                        | 'mrrGrowthRate'
                        | 'grossRevenueRetention'
                        | 'netRevenueRetention'
                        | 'churnRate'
                        | 'churnRate12m'
                        | 'customerChurnRate'
                        | 'customerChurnRate12m'
                        | 'grossProfitMargin'
                        | 'ruleOf40'
                        | 'cacPaybackPeriod'
                        | 'burnMultiple'
                    )[];
                    /** @description Compare the latest value up to this month (YYYY-MM). Defaults to the last complete month. */
                    month?: string;
                    /**
                     * @description MRR variant. cmrr = committed MRR (CMRR), mrr = recognised MRR.
                     * @default cmrr
                     * @enum {string}
                     */
                    mrrType?: 'cmrr' | 'mrr';
                    /** @description IANA time zone. Defaults to BatchContext.timeZone, then UTC. */
                    timeZone?: string;
                };
            };
        };
        responses: {
            /** @description benchmarks result */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    'application/json': {
                        asOfMonth: string;
                        /** @description The company's own peer group from its committed ARR and paying customers. Null until both are known. */
                        autoCell: {
                            /** @enum {string|null} */
                            acvSegment: 'mice' | 'rabbits' | 'deer' | 'elephants' | null;
                            /** @enum {string|null} */
                            arrStage:
                                | 'lt1m'
                                | 'from1to3m'
                                | 'from3to10m'
                                | 'from10to20m'
                                | 'gte20m'
                                | null;
                        } | null;
                        metrics: {
                            /** @description Peer quartiles in the metric units (fractions for percentages). Null when no sourced band exists for this peer group. */
                            bands: {
                                /** @enum {string} */
                                direction: 'higherIsBetter' | 'lowerIsBetter';
                                /** @description Bottom-quartile boundary (p25). */
                                lower: number;
                                median: number;
                                peerLabel: string;
                                /** @description Top-quartile boundary (p75). */
                                upper: number;
                            } | null;
                            /** @description False when the P&L is not categorized enough for an honest comparison (untagged cost of goods sold, operating expenses or sales and marketing spend). */
                            covered: boolean;
                            /** @enum {string} */
                            metric:
                                | 'mrrGrowthRateAnnual'
                                | 'mrrGrowthRate'
                                | 'grossRevenueRetention'
                                | 'netRevenueRetention'
                                | 'churnRate'
                                | 'churnRate12m'
                                | 'customerChurnRate'
                                | 'customerChurnRate12m'
                                | 'grossProfitMargin'
                                | 'ruleOf40'
                                | 'cacPaybackPeriod'
                                | 'burnMultiple';
                            note?: string;
                            /** @description Latest value in the 12 months up to asOfMonth. Null means no data. */
                            value: number | null;
                            valueMonth: string | null;
                            /**
                             * @description green = top quartile, yellow = between the quartiles, red = bottom quartile. Null without a value, without a band, or when the comparison is not trustworthy (see covered).
                             * @enum {string|null}
                             */
                            zone: 'green' | 'yellow' | 'red' | null;
                        }[];
                        /** @description The peer group compared against: overrides first, then the auto cell. */
                        peerCell: {
                            /** @enum {string|null} */
                            acvSegment: 'mice' | 'rabbits' | 'deer' | 'elephants' | null;
                            /** @enum {string|null} */
                            arrStage:
                                | 'lt1m'
                                | 'from1to3m'
                                | 'from3to10m'
                                | 'from10to20m'
                                | 'gte20m'
                                | null;
                        };
                    };
                };
            };
            /** @description Invalid params */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    'application/json': unknown;
                };
            };
            /** @description Caller lacks permission for this slice */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    'application/json': unknown;
                };
            };
        };
    };
