    getCompaniesByCompanyIdNotifications: {
        parameters: {
            query?: {
                /** @description Return notifications created on or after this date (YYYY-MM-DD). */
                createdAfter?: string;
                /** @description Return notifications created on or before this date (YYYY-MM-DD). */
                createdBefore?: string;
                /** @description For subscriptionChange notifications, return only this MRR event type: new, upgrade, downgrade, cancel, or reactivate. */
                eventType?: string;
                limit?: string;
                offset?: string;
                recipientUserId?: string;
                /** @description Comma-separated notification types to return, e.g. "bankConnectionError,subscriptionChange". Omit to return all types. */
                types?: string;
            };
            header?: never;
            path: {
                companyId: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Paginated list of notifications */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    'application/json': {
                        /** @description Date of the earliest notification (YYYY-MM-DD) for this company and recipient, ignoring the active filter; null if there are none. Used to anchor a date picker. */
                        earliestCreatedTime: string | null;
                        /** @description Avatar sidecar for the rows on this page. Notification rows carry ids, not counterparty data, so join against this map client-side rather than fetching each customer. */
                        entities: {
                            /** @description Customer avatars keyed by customer id, for the rows on this page. */
                            customers: {
                                [key: string]: {
                                    /** @description Known domains, used to resolve a logo. */
                                    domains: string[] | null;
                                    /** @description Resolved logo URL, or null when there is none. */
                                    logoUrl: string | null;
                                    /** @description Display name of the referenced entity. */
                                    name: string;
                                };
                            };
                        };
                        items: {
                            /** Format: uuid */
                            companyId: string;
                            /** Format: date-time */
                            createdTime: string | null;
                            createdUserId: string | null;
                            /** Format: uuid */
                            id: string;
                            /** Format: date-time */
                            lastUpdatedTime: string | null;
                            lastUpdatedUserId: string | null;
                            /** @description Type-specific notification data. */
                            payload: {
                                [key: string]: unknown;
                            } | null;
                            /**
                             * Format: date-time
                             * @description When the notification was read. Null if unread.
                             */
                            readTime: string | null;
                            /** @description The ID of the user who should receive this notification. */
                            recipientUserId: string;
                            /** @description The type of notification. */
                            type: string;
                        }[];
                        totalCount: number;
                    };
                };
            };
        };
    };
    postCompaniesByCompanyIdNotifications: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                companyId: string;
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                'application/json': {
                    /** @description The fields of the chosen type and nothing else, for example `transactionId`, `commentId`, `commentText` and `createdUserName` for `taggedInComment`. Unknown fields or wrong types are refused with 400. */
                    payload: {
                        [key: string]: unknown;
                    };
                    recipientUserId: string;
                    /**
                     * @description The notification type. Only the collaboration types can be created here; SaaSFlow raises all others itself.
                     * @enum {string}
                     */
                    type:
                        | 'assignedUser'
                        | 'bulkAssignedUser'
                        | 'taggedInComment'
                        | 'newComment'
                        | 'likedComment';
                };
            };
        };
        responses: {
            /** @description Created notification */
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    'application/json': {
                        /** Format: uuid */
                        companyId: string;
                        /** Format: date-time */
                        createdTime: string | null;
                        createdUserId: string | null;
                        /** Format: uuid */
                        id: string;
                        /** Format: date-time */
                        lastUpdatedTime: string | null;
                        lastUpdatedUserId: string | null;
                        /** @description Type-specific notification data. */
                        payload: {
                            [key: string]: unknown;
                        } | null;
                        /**
                         * Format: date-time
                         * @description When the notification was read. Null if unread.
                         */
                        readTime: string | null;
                        /** @description The ID of the user who should receive this notification. */
                        recipientUserId: string;
                        /** @description The type of notification. */
                        type: string;
                    };
                };
            };
            /** @description Payload does not match the notification type */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    'application/json': {
                        error: string;
                        issues: string[];
                    };
                };
            };
            /** @description Missing transactions:write, or users:manage for another recipient */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    'application/json': {
                        error: string;
                    };
                };
            };
        };
    };
