    getCompaniesByCompanyIdPlannedTransactionOccurrences: {
        parameters: {
            query: {
                /** @description Comma-separated account ids to restrict to. Omit the parameter for no filter; pass it empty to match none of them. */
                accountIds?: string;
                /** @description Comma-separated category ids to restrict to. Omit the parameter for no filter; pass it empty to match none of them, which combined with `showUncategorized=true` returns only the occurrences that have none assigned. */
                categoryIds?: string;
                /** @description Comma-separated customer / vendor ids to restrict to. Omit the parameter for no filter; pass it empty to match none of them, which combined with `showUnassignedCounterparty=true` returns only the occurrences that have none assigned. */
                counterpartyIds?: string;
                customerId?: string;
                /** @description Restrict to money coming in (`inflow`) or going out (`outflow`), judged on the gross amount `amount.value + passThroughTaxAmount`. Omit for both. */
                direction?: 'inflow' | 'outflow';
                endDate: string;
                /** @description When true, only occurrences backed by an issued invoice are returned (those with a non-null `invoice`), skipping predicted occurrences. Useful for listing overdue invoices in a past date range without dragging in stale predictions. */
                invoicedOnly?: '0' | '1' | 'true' | 'false';
                limit?: number;
                offset?: number | null;
                showUnassignedCounterparty?: '0' | '1' | 'true' | 'false';
                showUncategorized?: '0' | '1' | 'true' | 'false';
                startDate: string;
                vendorId?: string;
            };
            header?: never;
            path: {
                companyId: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Paginated list of planned transaction occurrences */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    'application/json': {
                        items: {
                            accountId: string | null;
                            /** @description Net amount of this occurrence, **excluding** pass-through taxes (e.g. VAT). Sign indicates direction (positive = inflow, negative = outflow). To compute the gross cash impact on the bank account, add `passThroughTaxAmount.value` when it is non-null. */
                            amount: {
                                currency: string;
                                value: number;
                            };
                            categoryId: string | null;
                            computedEndDate: string;
                            computedStartDate: string;
                            counterparty: {
                                id: string;
                                /** @enum {string} */
                                type: 'customer' | 'vendor';
                            } | null;
                            counterpartyLogoUrl: string | null;
                            counterpartyName: string | null;
                            date: string;
                            id: string;
                            /** @description Set when this occurrence is an invoice that has already been issued but is not paid yet, rather than a prediction. For those, `date` is when payment is expected (the due date) and `computedStartDate` / `computedEndDate` is the service period the invoice bills for. Null for predicted occurrences. */
                            invoice: {
                                /** @description Set when collection of this invoice looks stalled from our side: the provider has exhausted its payment retries, never attempted collection within a grace period, or the invoice is far past due. The string states the reason. Null while collection is still progressing normally. The invoice stays open with the provider — this is a heuristic, not a write-off. */
                                collectionStalled: string | null;
                                date: string;
                                externalId: string | null;
                                number: string | null;
                                url: string | null;
                            } | null;
                            name: string;
                            overrides: {
                                [key: string]: unknown;
                            };
                            /** @description Pass-through tax (e.g. VAT) collected or paid on top of `amount`, when applicable. Null when the planned transaction has no pass-through tax. This amount is **not** included in `amount` — add it to `amount.value` to get the gross cash flow that hits the bank account. */
                            passThroughTaxAmount: {
                                currency: string;
                                value: number;
                            } | null;
                            plannedTransactionId: string;
                            /** @description Recurrence configuration of a planned transaction: how often it repeats and when it stops. null for a one-off. */
                            recurrence: {
                                /** @description When the series stops: a last date, a number of occurrences, or null/omitted for open-ended. */
                                end?:
                                    | {
                                          /**
                                           * Format: date
                                           * @description Last possible occurrence date (YYYY-MM-DD).
                                           */
                                          date: string;
                                          /** @enum {string} */
                                          type: 'date';
                                      }
                                    | {
                                          /** @description Total number of occurrences. */
                                          count: number;
                                          /** @enum {string} */
                                          type: 'count';
                                      }
                                    | null;
                                /** @enum {string} */
                                frequency: 'day' | 'week' | 'month' | 'year';
                                /** @description Number of `frequency` units between occurrences. */
                                interval: number;
                                /** @description Pin monthly occurrences to the last day of the month. */
                                lastDayOfMonth?: boolean;
                            } | null;
                            source: string | null;
                            startDate: string;
                            usingPeriodDays: number;
                        }[];
                        totalCount: number;
                    };
                };
            };
        };
    };
