                            /** Format: uuid */
                            id: string;
                            /** Format: uuid */
                            integrationId: string | null;
                            /** @description True when this transaction is part of an open in-transit transfer (booked onto a transit account but not yet matched to the arriving side). Drives the "needs attention" indicator alongside the open status. */
